sections.push(h1("Performance Analysis"));
sections.push(bodyP("Cost pressure and regional competition remain the principal risks to monitor. We recommend expanding channel investment and rebalancing resourcing to sustain growth. The business delivered steady growth this quarter, with core KPIs on target."));

const doc = new Document({
