sections.push(h1("Summary and Recommendations"));
sections.push(bodyP("Revenue concentration in the main product line increased and retention improved. Cross-team efficiency rose and delivery lead times shortened versus last quarter. The business delivered steady growth this quarter, with core KPIs on target."));
sections.push(h1("Next-Step Plan"));
sections.push(bodyP("Cost pressure and regional competition remain the principal risks to monitor. We recommend expanding channel investment and rebalancing resourcing to sustain growth. The business delivered steady growth this quarter, with core KPIs on target."));

const doc = new Document({
